import collections

class MatchState:
    def __init__(self, predicate, next_state):
        self.predicate = predicate
        self.next_state = next_state

class EpsilonState:
    def __init__(self, next_states=None):
        self.next_states = next_states if next_states is not None else []

class AssertStartState:
    def __init__(self, next_state):
        self.next_state = next_state

class AssertEndState:
    def __init__(self, next_state):
        self.next_state = next_state

class AcceptState:
    pass

def connect(s1, s2):
    if isinstance(s1, EpsilonState):
        s1.next_states.append(s2)
    elif isinstance(s1, MatchState):
        s1.next_state = s2
    elif isinstance(s1, AssertStartState):
        s1.next_state = s2
    elif isinstance(s1, AssertEndState):
        s1.next_state = s2

def regex_search(pattern: str, text: str) -> bool:
    pos = 0

    def parse_expr():
        nonlocal pos
        frag = parse_term()
        while pos < len(pattern) and pattern[pos] == '|':
            pos += 1
            frag2 = parse_term()
            start = EpsilonState([frag[0], frag2[0]])
            end = EpsilonState()
            connect(frag[1], end)
            connect(frag2[1], end)
            frag = (start, end)
        return frag

    def parse_term():
        nonlocal pos
        start = EpsilonState()
        curr = start
        while pos < len(pattern) and pattern[pos] not in ')]|':
            frag = parse_factor()
            connect(curr, frag[0])
            curr = frag[1]
        end = EpsilonState()
        connect(curr, end)
        return (start, end)

    def parse_factor():
        nonlocal pos
        frag = parse_atom()
        while pos < len(pattern) and pattern[pos] in '*+?':
            op = pattern[pos]
            pos += 1
            start = EpsilonState()
            end = EpsilonState()
            if op == '*':
                start.next_states = [frag[0], end]
                connect(frag[1], frag[0])
                connect(frag[1], end)
            elif op == '+':
                start.next_states = [frag[0]]
                connect(frag[1], frag[0])
                connect(frag[1], end)
            elif op == '?':
                start.next_states = [frag[0], end]
                connect(frag[1], end)
            frag = (start, end)
        return frag

    def parse_atom():
        nonlocal pos
        if pos >= len(pattern):
            end = EpsilonState()
            return (end, end)

        char = pattern[pos]
        if char == '(':
            pos += 1
            frag = parse_expr()
            if pos >= len(pattern) or pattern[pos] != ')':
                raise ValueError("Unclosed (")
            pos += 1
            return frag
        elif char == '[':
            pos += 1
            negated = False
            if pos < len(pattern) and pattern[pos] == '^':
                negated = True
                pos += 1
            items = []
            while pos < len(pattern) and pattern[pos] != ']':
                if pattern[pos] == '\\':
                    pos += 1
                    if pos >= len(pattern): raise ValueError("Trailing backslash")
                    x = pattern[pos]
                    pos += 1
                else:
                    x = pattern[pos]
                    pos += 1
                if pos < len(pattern) and pattern[pos] == '-':
                    if pos + 1 < len(pattern) and pattern[pos+1] != ']':
                        pos += 1
                        if pos < len(pattern) and pattern[pos] == '\\':
                            pos += 1
                            if pos >= len(pattern): raise ValueError("Trailing backslash")
                            y = pattern[pos]
                            pos += 1
                        elif pos < len(pattern):
                            y = pattern[pos]
                            pos += 1
                        else: raise ValueError("Invalid range")
                        if ord(x) > ord(y): raise ValueError("Invalid range")
                        items.append((ord(x), ord(y)))
                    else:
                        items.append((ord(x), ord(x)))
                else:
                    items.append((ord(x), ord(x)))
            if pos >= len(pattern) or pattern[pos] != ']':
                raise ValueError("Unclosed [")
            pos += 1
            if not items: raise ValueError("Empty class")
            def predicate(c, items=items, negated=negated):
                cp = ord(c)
                match = any(low <= cp <= high for low, high in items)
                return not match if negated else match
            end = EpsilonState()
            return (MatchState(predicate, end), end)
        elif char == '.':
            pos += 1
            end = EpsilonState()
            return (MatchState(lambda c: True, end), end)
        elif char == '^':
            pos += 1
            end = EpsilonState()
            return (AssertStartState(end), end)
        elif char == '$':
            pos += 1
            end = EpsilonState()
            return (AssertEndState(end), end)
        elif char == '\\':
            pos += 1
            if pos >= len(pattern): raise ValueError("Trailing backslash")
            c = pattern[pos]
            pos += 1
            end = EpsilonState()
            return (MatchState(lambda char, target=c: char == target, end), end)
        else:
            pos += 1
            end = EpsilonState()
            return (MatchState(lambda char, target=char: char == target, end), end)

    if not pattern:
        return True

    try:
        frag = parse_expr()
    except IndexError:
        raise ValueError("Invalid pattern")

    s_start, s_end = frag
    s_end.next_states = [] # Clear connections to the sink
    accept = AcceptState()
    connect(s_end, accept)

    def epsilon_closure(states, index, text_len):
        closure = set(states)
        stack = list(states)
        while stack:
            s = stack.pop()
            if isinstance(s, EpsilonState):
                for ns in s.next_states:
                    if ns not in closure:
                        closure.add(ns)
                        stack.append(ns)
            elif isinstance(s, AssertStartState):
                if index == 0:
                    if s.next_state not in closure:
                        closure.add(s.next_state)
                        stack.append(s.next_state)
            elif isinstance(s, AssertEndState):
                if index == text_len:
                    if s.next_state not in closure:
                        closure.add(s.next_state)
                        stack.append(s.next_state)
        return closure

    pattern_starts_with_caret = pattern.startswith('^')
    current_states = set()
    text_len = len(text)

    for i in range(text_len + 1):
        if not pattern_starts_with_caret:
            current_states.add(s_start)
        elif i == 0:
            current_states.add(s_start)

        current_states = epsilon_closure(current_states, i, text_len)
        if any(isinstance(s, AcceptState) for s in current_states):
            return True

        if i < text_len:
            next_states = set()
            char = text[i]
            for s in current_states:
                if isinstance(s, MatchState) and s.predicate(char):
                    next_states.add(s.next_state)
            current_states = next_states
        else:
            current_states = set()

    return False

